import java.util.*;
import java.io.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;

    // Reads the next whitespace-separated token from stdin
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) st = new StringTokenizer(br.readLine());
        return st.nextToken();
    }

    static int nextInt() throws IOException { return Integer.parseInt(next()); }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        HashSet<Integer> a = new HashSet<>();
        for (int i = 0; i < n; i++) a.add(nextInt());
        int m = nextInt();
        TreeSet<Integer> common = new TreeSet<>();  // sorted and distinct
        for (int i = 0; i < m; i++) {
            int x = nextInt();
            if (a.contains(x)) common.add(x);
        }
        if (common.isEmpty()) { System.out.println(-1); return; }
        StringBuilder sb = new StringBuilder();
        for (int x : common) {
            if (sb.length() > 0) sb.append(' ');
            sb.append(x);
        }
        System.out.println(sb);
    }
}

